mapper.select:
select wt.*,wsio.owner_name stock_in_order_number,ww.warehouse_name ,wp.product_name,wco.order_number
from wms_tasks wt
left join wms_stock_in_orders wsio on wt.stock_in_order_id = wsio.id
left join wms_warehouses ww on wt.target_warehouse_id=ww.id
left join wms_products wp on wt.product_id = wp.id
left join wms_cargo_owners wco on wp.owner_id = wco.id

where 1=1


    and wt.task_number = #{taskNumber}


    and wt.task_type = #{taskType}


    and wt.task_status = #{taskStatus}


    and wsio.order_number = #{stockInOrderNumber}



    and wt.wave_order_id = #{waveOrderId}



    and wt.operator = #{operator}

order by wt.create_time desc
